// v24.xx (sndA4), HIS ORDER 2026-10-12 (improve the sound, a distinct noise for every action): BARE HANDS. A swing that missed played
// a full footstep on stone (the whiff sound was blip foot with no ground), and a swing that landed played the thin menu ping (a clank
// with no material), so a punch on a pillager sounded like a tap on a machine and a miss like a step. Now EVERY SWING whooshes (a
// 120 ms band of noise rising from 600 Hz to 2.2 kHz), so a whiff reads as a whiff, and A BLOW THAT LANDS thuds: the impact of what
// it struck (flesh or metal, as a round would), a heavy 180 to 70 Hz knock and a short low smack. The punch rides sfx with the
// material, so the party hears the same thing where it landed. No seeded draw.
SND_CAT.swing='foley'; SND_CAT.punch='imp';
NOISEMARK.punch={r:44,hear:620};
SNDA_GEN.swing=function(a,OUT,vol,t){
  if(!sndAGate('swing',0.08,t)) return;
  sndANoise(a,OUT,{dur:0.12,swell:0.5,ft:'bandpass',f0:600,f1:2200,q:1.2,g:0.08*vol,at:t});
};
SNDA_GEN.punch=function(a,OUT,vol,t,mat){
  if(!sndAGate('punch',0.05,t)) return;
  impactMat(a,OUT,'hit',(mat==='flesh'||mat==='armor')?mat:'metal',vol,t);
  sndATone(a,OUT,'sine',180,70,0.1,0.14*vol,t);
  sndANoise(a,OUT,{dur:0.04,pw:2.4,ft:'lowpass',f0:900,q:0.8,g:0.16*vol,at:t});
};
// v23.90, HIS ORDER 2026-10-12 (his #45, improve all sound as much as possible): FOOTSTEPS ON WHAT IS UNDER THEM.

